mapper.sql:
execution_row.task_id = #{filter.taskId}

  AND (execution_row.normalized_link LIKE CONCAT('%', #{filter.keyword}, '%')
    OR execution_row.group_jid LIKE CONCAT('%', #{filter.keyword}, '%'))


  AND execution_row.execution_status = #{filter.executionStatus}


  AND execution_row.stage = #{filter.stage}


  AND execution_row.wait_resource_type = #{filter.waitResourceType}


  AND execution_row.manual_paused = #{filter.manualPaused}

mapper.select:
SELECT execution_row.id AS executionId,
       COALESCE(material_facts.total_member_count, 0) AS totalMemberCount,
       COALESCE(material_facts.unconsumed_member_count, 0) AS unconsumedMemberCount,
       COALESCE(material_facts.submitted_member_count, 0) AS submittedMemberCount,
       COALESCE(material_facts.successful_member_count, 0) AS successfulMemberCount,
       COALESCE(material_facts.failed_member_count, 0) AS failedMemberCount,
       COALESCE(material_facts.unknown_member_count, 0) AS unknownMemberCount,
       COALESCE(material_facts.canceled_member_count, 0) AS canceledMemberCount,
       setting_row.required_manager_count AS requiredManagerCount,
       setting_row.puller_count_per_group AS plannedPullerCount,
       setting_row.station_count_per_call AS plannedStationCount,
       COALESCE(account_facts.current_manager_count, 0) AS currentManagerCount,
       COALESCE(account_facts.current_puller_count, 0) AS currentPullerCount,
       COALESCE(account_facts.current_station_count, 0) AS currentStationCount
FROM pull_task_group_execution execution_row
JOIN pull_task_standard_setting setting_row
  ON setting_row.task_id = execution_row.task_id
 AND setting_row.tenant_id = execution_row.tenant_id
LEFT JOIN (
  SELECT material_row.group_execution_id,
         COUNT(*) AS total_member_count,
         SUM(CASE WHEN material_row.pull_status = #{criteria.material.unconsumed}
                  THEN 1 ELSE 0 END) AS unconsumed_member_count,
         SUM(CASE WHEN material_row.pull_status = #{criteria.material.submitted}
                  THEN 1 ELSE 0 END) AS submitted_member_count,
         SUM(CASE WHEN material_row.pull_status = #{criteria.material.success}
                  THEN 1 ELSE 0 END) AS successful_member_count,
         SUM(CASE WHEN material_row.pull_status = #{criteria.material.failed}
                  THEN 1 ELSE 0 END) AS failed_member_count,
         SUM(CASE WHEN material_row.pull_status = #{criteria.material.unknown}
                  THEN 1 ELSE 0 END) AS unknown_member_count,
         SUM(CASE WHEN material_row.pull_status = #{criteria.material.canceled}
                  THEN 1 ELSE 0 END) AS canceled_member_count
  FROM pull_task_material_member material_row
  WHERE material_row.group_execution_id IN 
  GROUP BY material_row.group_execution_id
) material_facts ON material_facts.group_execution_id = execution_row.id
LEFT JOIN (
  SELECT account_row.group_execution_id,
         SUM(CASE WHEN account_row.role_type = #{criteria.account.managerRole}
                       AND account_row.availability_status = #{criteria.account.available}
                       AND account_row.membership_status = #{criteria.account.inGroup}
                       AND account_row.admin_status = #{criteria.account.adminSuccess}
                  THEN 1 ELSE 0 END) AS current_manager_count,
         SUM(CASE WHEN account_row.role_type = #{criteria.account.pullerRole}
                       AND account_row.availability_status = #{criteria.account.available}
                       AND account_row.membership_status = #{criteria.account.inGroup}
                       AND account_row.released_at IS NULL
                  THEN 1 ELSE 0 END) AS current_puller_count,
         SUM(CASE WHEN account_row.role_type = #{criteria.account.stationRole}
                       AND account_row.availability_status = #{criteria.account.available}
                       AND account_row.membership_status = #{criteria.account.inGroup}
                  THEN 1 ELSE 0 END) AS current_station_count
  FROM pull_task_group_account account_row
  WHERE account_row.group_execution_id IN 
  GROUP BY account_row.group_execution_id
) account_facts ON account_facts.group_execution_id = execution_row.id
WHERE execution_row.id IN 
ORDER BY execution_row.id ASC
